LEGACY_RECORDS = [{'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_1138', 'Revenue': '70.67', 'Demand': '1219', 'Initial Inventory': '9020'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_1691', 'Revenue': '100.0', 'Demand': '1127', 'Initial Inventory': '8370'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_1938', 'Revenue': '70.15', 'Demand': '1129', 'Initial Inventory': '8390'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_2047', 'Revenue': '100.0', 'Demand': '1176', 'Initial Inventory': '8680'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_2466', 'Revenue': '100.0', 'Demand': '1301', 'Initial Inventory': '9400'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_2610', 'Revenue': '65.77', 'Demand': '1340', 'Initial Inventory': '9900'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_2824', 'Revenue': '100.0', 'Demand': '1357', 'Initial Inventory': '9760'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_2834', 'Revenue': '100.0', 'Demand': '1158', 'Initial Inventory': '8610'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_3167', 'Revenue': '74.4', 'Demand': '1287', 'Initial Inventory': '9380'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_3505', 'Revenue': '81.14', 'Demand': '1281', 'Initial Inventory': '9170'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_3962', 'Revenue': '100.0', 'Demand': '1135', 'Initial Inventory': '8520'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/NRM_testing/NRM15/SampleSalesData.csv', 'values': {'Product Name': 'S700_4002', 'Revenue': '61.44', 'Demand': '1392', 'Initial Inventory': '10290'}}]
import gurobipy as gp
from gurobipy import GRB
products = []
revenue = {}
demand = {}
inventory = {}
for rec in LEGACY_RECORDS:
    vals = rec['values']
    pname = vals['Product Name']
    if pname.startswith('S700_'):
        products.append(pname)
        try:
            revenue[pname] = float(vals['Revenue'])
            demand[pname] = int(vals['Demand'])
            inventory[pname] = int(vals['Initial Inventory'])
        except Exception as e:
            raise ValueError(f'Invalid data for product {pname}: {e}')
for pname in products:
    if pname not in revenue or pname not in demand or pname not in inventory:
        raise ValueError(f'Missing data for product {pname}')
m = gp.Model('S700_Fulfillment')
x_vars = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((revenue[p] * x_vars[p] for p in products)), GRB.MAXIMIZE)
m.addConstrs((x_vars[p] <= inventory[p] for p in products), name='')
m.addConstrs((x_vars[p] <= demand[p] for p in products), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')